result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "app.py", "content": """"Flask app exposing keyset (/rank) and naive OFFSET (/rank_offset) ranking pages.

Ordering everywhere: score DESC, id ASC (deterministic tiebreak).
"""
import os
import sqlite3
import time

from flask import Flask, jsonify, request, make_response

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "ranking.db")
DEFAULT_LIMIT = 50
MAX_LIMIT = 1000

app = Flask(__name__)

KEYSET_FIRST = (
    "SELECT id, score FROM ranking "
    "WHERE category = ? "
    "ORDER BY score DESC, id ASC "
    "LIMIT ?"
)
# Seek directly past the last seen (score, id); the composite index
# (category, score DESC, id ASC) makes this an index seek + 50-row read,
# regardless of how deep the page is.
KEYSET_AFTER = (
    "SELECT id, score FROM ranking "
    "WHERE category = ? AND (score < ? OR (score = ? AND id > ?)) "
    "ORDER BY score DESC, id ASC "
    "LIMIT ?"
)
OFFSET_PAGE = (
    "SELECT id, score FROM ranking "
    "WHERE category = ? "
    "ORDER BY score DESC, id ASC "
    "LIMIT ? OFFSET ?"
)


def _query(sql, params):
    con = sqlite3.connect(DB_PATH)
    try:
        return con.execute(sql, params).fetchall()
    finally:
        con.close()


def _get_limit():
    raw = request.args.get("limit")
    if raw is None:
        return DEFAULT_LIMIT
    try:
        limit = int(raw)
    except ValueError:
        raise ValueError("limit must be an integer")
    if not (1 <= limit <= MAX_LIMIT):
        raise ValueError(f"limit must be in [1, {MAX_LIMIT}]")
    return limit


def _respond(rows, next_cursor, took_s):
    body = {
        "rows": [{"id": i, "score": s} for (i, s) in rows],
        "next_cursor": next_cursor,
    }
    resp = make_response(jsonify(body))
    resp.headers["X-Took-Ms"] = f"{took_s * 1000:.3f}"
    return resp


@app.get("/rank")
def rank_keyset():
    """Keyset ('search-after') pagination.

    Page 1: GET /rank?category=a&limit=50
    Next:   GET /rank?category=a&limit=50&after_score=<last score>&after_id=<last id>
    """
    try:
        category = request.args.get("category", "a")
        limit = _get_limit()
        after_score = request.args.get("after_score")
        after_id = request.args.get("after_id")
        if (after_score is None) != (after_id is None):
            raise ValueError("after_score and after_id must be provided together")
        if after_score is not None:
            s = float(after_score)
            i = int(after_id)
            sql, params = KEYSET_AFTER, (category, s, s, i, limit)
        else:
            sql, params = KEYSET_FIRST, (category, limit)
    except ValueError as exc:
        return jsonify(error=str(exc)), 400

    t0 = time.perf_counter()
    rows = _query(sql, params)
    took = time.perf_counter() - t0

    next_cursor = None
    if len(rows) == limit:
        last_id, last_score = rows[-1]
        next_cursor = {"after_score": repr(last_score), "after_id": last_id}
    return _respond(rows, next_cursor, took)


@app.get("/rank_offset")
def rank_offset():
    """Naive OFFSET pagination — SQLite must walk and discard `offset` index
    entries before returning the page, so cost grows linearly with depth."""
    try:
        category = request.args.get("category", "a")
        limit = _get_limit()
        offset = int(request.args["offset"]) if "offset" in request.args else 0
        if offset < 0:
            raise ValueError("offset must be >= 0")
    except (ValueError, KeyError) as exc:
        return jsonify(error=str(exc)), 400

    t0 = time.perf_counter()
    rows = _query(OFFSET_PAGE, (category, limit, offset))
    took = time.perf_counter() - t0

    return _respond(rows, None, took)


@app.get("/health")
def health():
    return jsonify(ok=True)


if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5001, threaded=True)
"})
